63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /**
69	     * Dedicated audit logger recording successful owner creations, including the authenticated
70	     * user and the new owner's id and membership number.
71	     */
72	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
73	
74	    /**
75	     * The maximum number of owners that may be registered on any single day (by registration date).
76	     * Once this many owners already carry today's registration date, further creation is rejected.
77	     */
78	    private static final int MAX_OWNERS_PER_DAY = 20;
79	
80	    /**
81	     * The maximum number of owners permitted in any single city. Once a city already contains
82	     * this many owners, creating a further owner in that city is rejected. Cities are matched
83	     * ignoring letter case.
84	     */
85	    private static final int MAX_OWNERS_PER_CITY = 8;
86	
87	    /**
88	     * The number of owners, counted from the very first ever created, that receive the
89	     * {@code FOUNDING} membership tier. Owners created once this many already exist receive
90	     * the {@code STANDARD} tier instead.
91	     */
92	    private static final int FOUNDING_MEMBERSHIP_LIMIT = 100;
93	
94	    /**
95	     * The number of existing owners that must already share a new owner's telephone area code
96	     * (the first three digits) before the creation is flagged, via a WARN to the AUDIT logger,
97	     * as a possible bulk signup.
98	     */
99	    private static final int BULK_AREA_CODE_THRESHOLD = 5;
100	
101	    private final ClinicService clinicService;
102	
103	    private final OwnerMapper ownerMapper;
104	
105	    private final PetMapper petMapper;
106	
107	    private final VisitMapper visitMapper;
108	
109	    public OwnerRestControllerV1(ClinicService clinicService,
110	                                 OwnerMapper ownerMapper,
111	                                 PetMapper petMapper,
112	                                 VisitMapper visitMapper) {
113	        this.clinicService = clinicService;
114	        this.ownerMapper = ownerMapper;
115	        this.petMapper = petMapper;
116	        this.visitMapper = visitMapper;
117	    }
