119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
122	        Collection<Owner> owners;
123	        if (lastName != null) {
124	            owners = this.clinicService.findOwnerByLastName(lastName);
125	        } else {
126	            owners = this.clinicService.findAllOwners();
127	        }
128	        if (owners.isEmpty()) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
137	        Owner owner = this.clinicService.findOwnerById(ownerId);
138	        if (owner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
147	        HttpHeaders headers = new HttpHeaders();
148	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
149	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
150	        if (owner.getRegistrationDate() == null) {
151	            owner.setRegistrationDate(LocalDate.now());
152	        }
153	        if (isDailyRegistrationLimitReached()) {
154	            throw new DailyOwnerRegistrationLimitException(
155	                "The maximum of " + MAX_OWNERS_PER_DAY
156	                    + " owners that may be registered today has already been reached");
157	        }
158	        if (isDuplicateTelephone(owner)) {
159	            throw new DuplicateOwnerException("An owner with telephone "
160	                + owner.getTelephone() + " already exists");
161	        }
162	        if (isDuplicateEmail(owner)) {
163	            throw new DuplicateOwnerException("An owner with email "
164	                + owner.getEmail() + " already exists");
165	        }
166	        if (isCityOwnerLimitReached(owner.getCity())) {
167	            throw new CityOwnerLimitException("The city " + owner.getCity()
168	                + " already contains the maximum of " + MAX_OWNERS_PER_CITY + " owners");
169	        }
170	        boolean bulkAreaCodeSignup = isBulkAreaCodeSignup(owner.getTelephone());
171	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
172	        owner.setMembershipNumber(membershipNumber);
173	        owner.setMembershipTier(membershipNumber <= FOUNDING_MEMBERSHIP_LIMIT ? "FOUNDING" : "STANDARD");
174	        owner.setNamesakeCount(countNamesakes(owner.getLastName()));
175	        owner.setSharesHousehold(sharesHousehold(owner.getAddress(), owner.getCity()));
176	        owner.setLocality(resolveLocality(owner.getCity()));
177	        owner.setCity(resolveCity(owner.getCity()));
178	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
179	        this.clinicService.saveOwner(owner);
180	        AUDIT.info("Owner created by user={} ownerId={} membershipNumber={}",
181	            currentUsername(), owner.getId(), owner.getMembershipNumber());
182	        if (bulkAreaCodeSignup) {
183	            AUDIT.warn("Possible bulk signup: owner ownerId={} shares telephone area code {} "
184	                    + "with {} or more existing owners",
185	                owner.getId(), areaCode(owner.getTelephone()), BULK_AREA_CODE_THRESHOLD);
186	        }
187	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
188	        headers.setLocation(UriComponentsBuilder.newInstance()
189	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
190	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
191	    }
192	
193	    /**
194	     * Determines whether the maximum number of owner registrations permitted for today has
195	     * already been reached. Owners are counted by registration date, comparing against the
196	     * current day, so the limit resets at midnight.
197	     *
198	     * @return {@code true} if at least {@link #MAX_OWNERS_PER_DAY} owners already carry today's
199	     *         registration date
200	     */
201	    private boolean isDailyRegistrationLimitReached() {
202	        LocalDate today = LocalDate.now();
203	        long registeredToday = this.clinicService.findAllOwners().stream()
204	            .filter(existing -> today.equals(existing.getRegistrationDate()))
205	            .count();
206	        return registeredToday >= MAX_OWNERS_PER_DAY;
207	    }
208	
209	    /**
210	     * Determines whether the given city already contains the maximum number of owners permitted
211	     * per city. Owners are counted by matching their city ignoring letter case. A {@code null}
212	     * city is never considered to have reached the limit.
213	     *
214	     * @param city the city of the owner about to be created
215	     * @return {@code true} if at least {@link #MAX_OWNERS_PER_CITY} owners already reside in the
216	     *         given city
217	     */
218	    private boolean isCityOwnerLimitReached(String city) {
219	        if (city == null) {
220	            return false;
221	        }
222	        long ownersInCity = this.clinicService.findAllOwners().stream()
223	            .filter(existing -> existing.getCity() != null
224	                && existing.getCity().equalsIgnoreCase(city))
225	            .count();
226	        return ownersInCity >= MAX_OWNERS_PER_CITY;
227	    }
228	
229	    /**
230	     * Determines whether any other owner already uses the candidate's telephone number.
231	     * The comparison ignores letter case and surrounding or repeated whitespace.
232	     *
233	     * @param candidate the owner about to be created
234	     * @return {@code true} if an owner with the same telephone is already present in the data store
235	     */
236	    private boolean isDuplicateTelephone(Owner candidate) {
237	        String telephone = normalizeTelephone(candidate.getTelephone());
238	        return this.clinicService.findAllOwners().stream()
239	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
240	    }
241	
242	    /**
243	     * Canonicalises a telephone number by stripping every character that is not a digit
244	     * (for example spaces, dashes and parentheses), so that {@code "(613) 555-0100"} and
245	     * {@code "6135550100"} are treated as the same number. This is the form persisted for
246	     * an owner and used for the telephone-uniqueness check.
247	     *
248	     * @param telephone the raw telephone value, possibly {@code null}
249	     * @return the digits-only telephone, or {@code null} if {@code telephone} was {@code null}
250	     */
251	    private static String normalizeTelephone(String telephone) {
252	        if (telephone == null) {
253	            return null;
254	        }
255	        return telephone.replaceAll("[^0-9]", "");
256	    }
257	
258	    /**
259	     * Determines whether creating an owner with the given telephone should be flagged as a
260	     * possible bulk signup. This is the case when {@link #BULK_AREA_CODE_THRESHOLD} or more
261	     * existing owners already share the candidate's telephone area code (the first three digits
262	     * of the digits-only telephone). Owners whose telephone has fewer than three digits, and a
263	     * {@code null} candidate telephone, never trigger the flag. Evaluated before the new owner is
264	     * saved, so only pre-existing owners are counted.
265	     *
266	     * @param telephone the (already normalised) telephone of the owner about to be created
267	     * @return {@code true} if at least {@link #BULK_AREA_CODE_THRESHOLD} existing owners share the
268	     *         same telephone area code
269	     */
270	    private boolean isBulkAreaCodeSignup(String telephone) {
271	        String areaCode = areaCode(telephone);
272	        if (areaCode == null) {
273	            return false;
274	        }
275	        long sharing = this.clinicService.findAllOwners().stream()
276	            .filter(existing -> areaCode.equals(areaCode(existing.getTelephone())))
277	            .count();
278	        return sharing >= BULK_AREA_CODE_THRESHOLD;
279	    }
280	
281	    /**
282	     * Extracts the area code (the first three digits) of a telephone number after stripping any
283	     * non-digit characters.
284	     *
285	     * @param telephone the raw telephone value, possibly {@code null}
286	     * @return the three-digit area code, or {@code null} if the telephone is {@code null} or has
287	     *         fewer than three digits
288	     */
289	    private static String areaCode(String telephone) {
290	        String digits = normalizeTelephone(telephone);
291	        if (digits == null || digits.length() < 3) {
292	            return null;
293	        }
294	        return digits.substring(0, 3);
295	    }
296	
297	    /**
298	     * Determines whether any other owner already uses the candidate's email address.
299	     * An absent or blank email is never considered a duplicate. The comparison ignores
300	     * letter case and surrounding or repeated whitespace.
301	     *
302	     * @param candidate the owner about to be created
303	     * @return {@code true} if an owner with the same email is already present in the data store
304	     */
305	    private boolean isDuplicateEmail(Owner candidate) {
306	        String email = normalize(candidate.getEmail());
307	        if (email == null || email.isBlank()) {
308	            return false;
309	        }
310	        return this.clinicService.findAllOwners().stream()
311	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
312	    }
313	
314	    /**
315	     * Builds the customer code for a newly created owner, formatted as
316	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of
317	     * owners already present in the same city, zero-padded to four digits
318	     * (e.g. {@code 'LONDON-0007'}). Cities are matched ignoring letter case.
319	     *
320	     * @param city the city of the owner about to be created
321	     * @return the formatted customer code
322	     */
323	    /**
324	     * Resolves the city name to store for a newly created owner. The supplied city is
325	     * normalised to title case (each word's first letter upper-cased, the rest lower-cased),
326	     * so that {@code "new york"} and {@code "NEW YORK"} both become {@code "New York"}.
327	     * However, if an owner already exists in that city (matched ignoring letter case), that
328	     * existing owner's exact spelling of the city is reused instead, so a single canonical
329	     * spelling is kept per city (for example an existing {@code "McFarland"} is preserved
330	     * rather than being flattened to {@code "Mcfarland"}).
331	     *
332	     * @param city the raw city supplied for the owner about to be created
333	     * @return the existing owner's spelling if the city is already known, otherwise the
334	     *         title-cased city; {@code null} if {@code city} was {@code null}
335	     */
336	    private String resolveCity(String city) {
337	        if (city == null) {
338	            return null;
339	        }
340	        return this.clinicService.findAllOwners().stream()
341	            .map(Owner::getCity)
342	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
343	            .findFirst()
344	            .orElseGet(() -> titleCase(city));
345	    }
346	
347	    /**
348	     * Converts a city name to title case: each whitespace-separated word has its first letter
349	     * upper-cased and its remaining letters lower-cased, while the original whitespace is left
350	     * untouched. For example {@code "san   FRANCISCO"} becomes {@code "San   Francisco"}.
351	     *
352	     * @param city the city to title-case
353	     * @return the title-cased city
354	     */
355	    private static String titleCase(String city) {
356	        StringBuilder result = new StringBuilder(city.length());
357	        boolean startOfWord = true;
358	        for (int i = 0; i < city.length(); i++) {
359	            char c = city.charAt(i);
360	            if (Character.isWhitespace(c)) {
361	                startOfWord = true;
362	                result.append(c);
363	            } else if (startOfWord) {
364	                result.append(Character.toTitleCase(c));
365	                startOfWord = false;
366	            } else {
367	                result.append(Character.toLowerCase(c));
368	            }
369	        }
370	        return result.toString();
371	    }
372	
373	    /**
374	     * Counts how many owners already present in the data store share the given last name,
375	     * ignoring letter case. This is evaluated before the new owner is saved, so it reflects
376	     * the number of <em>other</em> owners carrying that last name at creation time.
377	     *
378	     * @param lastName the last name of the owner about to be created
379	     * @return the number of existing owners with the same last name; {@code 0} if the last
380	     *         name is {@code null}
381	     */
382	    private int countNamesakes(String lastName) {
383	        if (lastName == null) {
384	            return 0;
385	        }
386	        return (int) this.clinicService.findAllOwners().stream()
387	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
388	            .count();
389	    }
390	
391	    /**
392	     * Determines whether another owner already resides at the same address and city as the owner
393	     * about to be created. Both address and city are matched ignoring letter case. This is
394	     * evaluated before the new owner is saved, so it reflects only owners that already existed.
395	     *
396	     * @param address the address of the owner about to be created
397	     * @param city    the city of the owner about to be created
398	     * @return {@code true} if an existing owner already has the same address and city
399	     */
400	    /**
401	     * Determines the locality of the owner about to be created relative to the existing clientele.
402	     * The result is {@code "local"} if the owner's city is the single most common city among all
403	     * owners that already exist, and {@code "remote"} otherwise. Cities are grouped ignoring letter
404	     * case. If there are no existing owners, or if two or more cities are tied for the most common
405	     * (so there is no single most common city), the result is {@code "remote"}.
406	     *
407	     * @param city the city of the owner about to be created
408	     * @return {@code "local"} if the city is the single most common among existing owners,
409	     *         otherwise {@code "remote"}
410	     */
411	    private String resolveLocality(String city) {
412	        if (city == null) {
413	            return "remote";
414	        }
415	        Map<String, Long> countsByCity = this.clinicService.findAllOwners().stream()
416	            .map(Owner::getCity)
417	            .filter(Objects::nonNull)
418	            .collect(Collectors.groupingBy(existing -> existing.toLowerCase(Locale.ROOT),
419	                Collectors.counting()));
420	        long maxCount = countsByCity.values().stream()
421	            .mapToLong(Long::longValue)
422	            .max()
423	            .orElse(0L);
424	        if (maxCount == 0L) {
425	            return "remote";
426	        }
427	        List<String> mostCommonCities = countsByCity.entrySet().stream()
428	            .filter(entry -> entry.getValue() == maxCount)
429	            .map(Map.Entry::getKey)
430	            .toList();
431	        if (mostCommonCities.size() != 1) {
432	            return "remote";
433	        }
434	        return mostCommonCities.get(0).equals(city.toLowerCase(Locale.ROOT)) ? "local" : "remote";
435	    }
436	
437	    private boolean sharesHousehold(String address, String city) {
438	        if (address == null || city == null) {
439	            return false;
440	        }
441	        return this.clinicService.findAllOwners().stream()
442	            .anyMatch(existing -> address.equalsIgnoreCase(existing.getAddress())
443	                && city.equalsIgnoreCase(existing.getCity()));
444	    }
445	
446	    private String nextCustomerCode(String city) {
447	        long ownersInCity = this.clinicService.findAllOwners().stream()
448	            .filter(existing -> existing.getCity() != null
449	                && existing.getCity().equalsIgnoreCase(city))
450	            .count();
451	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
452	    }
453	
454	    /**
455	     * Canonicalises a value for duplicate detection so that comparisons ignore letter
456	     * case and surrounding or repeated whitespace. Surrounding whitespace is stripped,
457	     * any run of internal whitespace is collapsed to a single space, and the result is
458	     * lower-cased. For example {@code "  john   smith "} and {@code "John Smith"} both
459	     * normalise to {@code "john smith"}.
460	     *
461	     * @param value the raw value, possibly {@code null}
462	     * @return the normalised value, or {@code null} if {@code value} was {@code null}
463	     */
464	    private static String normalize(String value) {
465	        if (value == null) {
466	            return null;
467	        }
468	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
469	    }
470	
471	    /**
472	     * Resolves the name of the currently authenticated user for audit logging.
473	     *
474	     * @return the authenticated user's name, or {@code "anonymous"} if there is no authentication
475	     */
476	    private static String currentUsername() {
477	        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
478	        if (authentication == null || authentication.getName() == null) {
479	            return "anonymous";
480	        }
481	        return authentication.getName();
482	    }
