484	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
485	    @Override
486	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
487	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
488	        if (currentOwner == null) {
489	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
490	        }
491	        currentOwner.setAddress(ownerFieldsDto.getAddress());
492	        currentOwner.setCity(ownerFieldsDto.getCity());
493	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
494	        currentOwner.setLastName(ownerFieldsDto.getLastName());
495	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
496	        this.clinicService.saveOwner(currentOwner);
497	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
498	    }
499	
500	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
501	    @Transactional
502	    @Override
503	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
504	        Owner owner = this.clinicService.findOwnerById(ownerId);
505	        if (owner == null) {
506	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
507	        }
508	        this.clinicService.deleteOwner(owner);
509	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
510	    }
