512	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
513	    @Override
514	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
515	        Owner owner = this.clinicService.findOwnerById(ownerId);
516	        if (owner == null) {
517	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
518	        }
519	        HttpHeaders headers = new HttpHeaders();
520	        Pet pet = petMapper.toPet(petFieldsDto);
521	        owner.setId(ownerId);
522	        pet.setOwner(owner);
523	        pet.getType().setName(null);
524	        this.clinicService.savePet(pet);
525	        PetDto petDto = petMapper.toPetDto(pet);
526	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
527	            .buildAndExpand(pet.getId()).toUri());
528	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
529	    }
