531	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
532	    @Override
533	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
534	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
535	        if (currentOwner != null) {
536	            Pet currentPet = this.clinicService.findPetById(petId);
537	            if (currentPet != null) {
538	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
539	                currentPet.setName(petFieldsDto.getName());
540	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
541	                this.clinicService.savePet(currentPet);
542	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
543	            }
544	        }
545	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
546	    }
