548	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
549	    @Override
550	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
551	        HttpHeaders headers = new HttpHeaders();
